1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync, validateWorkflow } from '../src/engine.js';
4	
5	const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
6	
7	// A linear trigger -> end workflow usable by the synchronous entry.
8	function linearEndWorkflow(endResult) {
9	  return {
10	    id: 'linear-end',
11	    entry: 'start',
12	    nodes: [
13	      { id: 'start', type: 'trigger', next: 'finish' },
14	      { id: 'finish', type: 'end', result: endResult },
15	    ],
16	  };
17	}
18	
19	// A single-end workflow whose end carries a nested approval result. Array
20	// successors force the "exactly one end node" rule, which is also what lets
21	// the end run before another activated branch's business action finishes.
22	function approvalWorkflow(endResult) {
23	  return {
24	    id: 'approval',
25	    entry: 'start',
26	    nodes: [
27	      { id: 'start', type: 'trigger', next: ['finish', 'work'] },
28	      { id: 'finish', type: 'end', result: endResult },
29	      { id: 'work', type: 'action', operation: 'work', next: 'finish' },
30	    ],
31	  };
32	}
33	
34	const approvalPayload = () => ({
35	  verdict: 'approved',
36	  approver: { id: 'u-7', name: 'Lee' },
37	  details: [
38	    { item: 'keyboard', qty: 2 },
39	    { item: 'monitor', qty: 1 },
40	  ],
41	  flags: { urgent: false, tags: ['finance'] },
42	});
43	
44	test('synchronous run returns an independent deep copy of an object end result', () => {
45	  const workflow = linearEndWorkflow(approvalPayload());
46	  const first = executeWorkflow(workflow, {});
47	  assert.equal(first.status, 'completed');
48	
49	  // The caller can freely edit fields, add/delete nested properties and
50	  // change array contents of the value it received.
51	  first.result.verdict = 'rejected';
52	  first.result.approver.name = 'Someone Else';
53	  first.result.details[0].qty = 99;
54	  first.result.details.push({ item: 'webcam', qty: 3 });
55	  delete first.result.flags.tags;
56	  first.result.extra = { nested: [1, 2, 3] };
57	
58	  // The definition keeps its configured content, nested levels included.
59	  assert.equal(workflow.nodes[1].result.verdict, 'approved');
60	  assert.equal(workflow.nodes[1].result.approver.name, 'Lee');
61	  assert.equal(workflow.nodes[1].result.details[0].qty, 2);
62	  assert.deepEqual(workflow.nodes[1].result.details.map(d => d.item), ['keyboard', 'monitor']);
63	  assert.equal(Object.hasOwn(workflow.nodes[1].result.flags, 'tags'), true);
64	  assert.equal('extra' in workflow.nodes[1].result, false);
65	
66	  // Re-running the same definition still yields the configured content.
67	  const second = executeWorkflow(workflow, {});
68	  assert.deepEqual(second.result, approvalPayload());
69	  assert.notEqual(second.result, workflow.nodes[1].result);
70	  assert.notEqual(second.result.details, workflow.nodes[1].result.details);
71	
72	  // Editing one run's result cannot change another completed run's result.
73	  first.result.details.length = 0;
74	  assert.equal(second.result.details.length, 2);
75	});
