77	test('arrays at the top level and primitive leaves are isolated too', () => {
78	  const workflow = linearEndWorkflow({ rows: [{ n: 1 }, { n: 2 }] });
79	  const execution = executeWorkflow(workflow, {});
80	  execution.result.rows[0].n = 100;
81	  execution.result.rows.pop();
82	  assert.deepEqual(workflow.nodes[1].result.rows, [{ n: 1 }, { n: 2 }]);
83	  assert.deepEqual(executeWorkflow(workflow, {}).result.rows, [{ n: 1 }, { n: 2 }]);
84	});
