86	test('asynchronous run follows the same deep-copy isolation rules', async () => {
87	  const workflow = approvalWorkflow(approvalPayload());
88	  const execution = await executeWorkflowAsync(workflow, {}, { work: () => 'done' });
89	  assert.equal(execution.status, 'completed');
90	
91	  execution.result.verdict = 'rejected';
92	  execution.result.details[1].item = 'changed';
93	  execution.result.flags.tags.push('tampered');
94	
95	  assert.equal(workflow.nodes[1].result.verdict, 'approved');
96	  assert.equal(workflow.nodes[1].result.details[1].item, 'monitor');
97	  assert.deepEqual(workflow.nodes[1].result.flags.tags, ['finance']);
98	
99	  const another = await executeWorkflowAsync(workflow, {}, { work: () => 'done' });
100	  assert.deepEqual(another.result, approvalPayload());
101	  assert.notEqual(another.result, execution.result);
102	});
