104	test('unset, null and primitive results keep their exact values', async () => {
105	  const cases = [
106	    ['absent', undefined, value => assert.equal(value, null)],
107	    ['null', null, value => assert.equal(value, null)],
108	    ['empty string', '', value => assert.equal(value, '')],
109	    ['zero', 0, value => assert.equal(value, 0)],
110	    ['false', false, value => assert.equal(value, false)],
111	    ['number', 42, value => assert.equal(value, 42)],
112	    ['boolean', true, value => assert.equal(value, true)],
113	  ];
114	  for (const [label, configured, check] of cases) {
115	    const workflow = {
116	      id: `primitive-${label}`,
117	      entry: 'start',
118	      nodes: [
119	        { id: 'start', type: 'trigger', next: 'done' },
120	        configured === undefined
121	          ? { id: 'done', type: 'end' }
122	          : { id: 'done', type: 'end', result: configured },
123	      ],
124	    };
125	    const sync = executeWorkflow(workflow, {});
126	    check(sync.result);
127	  }
128	
129	  // The asynchronous entry preserves them as well, especially 0 and false.
130	  for (const configured of [0, false, '']) {
131	    const workflow = {
132	      id: 'async-primitives', entry: 'start',
133	      nodes: [
134	        { id: 'start', type: 'trigger', next: 'done' },
135	        { id: 'done', type: 'end', result: configured },
136	      ],
137	    };
138	    const execution = await executeWorkflowAsync(workflow, {});
139	    assert.equal(execution.result, configured);
140	  }
141	});
