143	test('end result recorded before a waiting branch is immune to definition mutation during the wait', async () => {
144	  const workflow = {
145	    id: 'early-end-wait', entry: 'start',
146	    nodes: [
147	      { id: 'start', type: 'trigger', next: ['finish', 'work'] },
148	      { id: 'finish', type: 'end', result: approvalPayload() },
149	      { id: 'work', type: 'action', operation: 'slow', next: 'finish' },
150	    ],
151	  };
152	  const execution = await executeWorkflowAsync(workflow, {}, {
153	    slow: async () => {
154	      // The end node has already run; mutate the definition's result object
155	      // while this branch is still waiting.
156	      setTimeout(() => {
157	        workflow.nodes[1].result.verdict = 'tampered';
158	        workflow.nodes[1].result.details[0].item = 'tampered-item';
159	        workflow.nodes[1].result.details.push({ item: 'late', qty: 9 });
160	      }, 10);
161	      await sleep(40);
162	      return 'done';
163	    },
164	  });
165	
166	  assert.equal(execution.status, 'completed');
167	  assert.deepEqual(execution.result, approvalPayload());
168	  // The mutation really happened on the definition; only the recorded result
169	  // was protected.
170	  assert.equal(workflow.nodes[1].result.verdict, 'tampered');
171	});
