302	// ---------------------------------------------------------------------------
303	// End results whose structured clone retains shared memory
304	// ---------------------------------------------------------------------------
305	
306	// A compensable business action precedes the end: when definition validation
307	// rejects the result, that action and its compensation must never be invoked.
308	function businessBeforeEndWorkflow(endResult) {
309	  return {
310	    id: 'business-before-end',
311	    entry: 'start',
312	    nodes: [
313	      { id: 'start', type: 'trigger', next: 'early' },
314	      {
315	        id: 'early', type: 'action', operation: 'opEarly',
316	        compensation: { operation: 'undoEarly' }, next: 'finish',
317	      },
318	      { id: 'finish', type: 'end', result: endResult },
319	    ],
320	  };
321	}
322	
323	function assertEndSharedMemoryError(error, nodeId = 'finish') {
324	  assert.ok(error instanceof Error, 'a definition error (plain Error) is thrown/rejected');
325	  assert.ok(!(error instanceof TypeError), 'shared-memory end results are a definition error, not a TypeError');
326	  assert.match(error.message, new RegExp(`end node ${nodeId}: result contains shared memory`));
327	  assert.match(error.message, /SharedArrayBuffer/);
328	  assert.match(error.message, /independent copies cannot be guaranteed/);
329	}
330	
331	// Every result below retains shared memory in the content its structured clone
332	// actually saves.
333	function sharedResults() {
334	  const cyclic = () => {
335	    const value = { label: 'self' };
336	    value.myself = value;
337	    value.shared = new SharedArrayBuffer(2);
338	    return value;
339	  };
340	  const aliased = () => {
341	    const shared = new SharedArrayBuffer(2);
342	    const holder = { buffer: shared };
343	    return { a: holder, b: holder, list: [shared] };
344	  };
345	  const causeIsNonEnumerable = () => {
346	    const error = new Error('wrap', { cause: new Uint8Array(new SharedArrayBuffer(2)) });
347	    // The Error constructor installs "cause" as a non-enumerable own
348	    // property; it must still count because the clone retains it.
349	    assert.equal(Object.getOwnPropertyDescriptor(error, 'cause').enumerable, false);
350	    return error;
351	  };
352	  return [
353	    () => new SharedArrayBuffer(4),
354	    () => new Uint8Array(new SharedArrayBuffer(4)),
355	    () => new Int32Array(new SharedArrayBuffer(8)),
356	    () => new Float64Array(new SharedArrayBuffer(8)),
357	    () => new BigInt64Array(new SharedArrayBuffer(8)),
358	    () => new DataView(new SharedArrayBuffer(4)),
359	    () => new Uint8Array(new SharedArrayBuffer(8), 2, 3),
360	    () => ({ inner: { bytes: new SharedArrayBuffer(4) } }),
361	    () => ({ list: [1, [2, new Uint8Array(new SharedArrayBuffer(4))]] }),
362	    () => [new SharedArrayBuffer(4)],
363	    () => new Map([['k', new SharedArrayBuffer(4)]]),
364	    () => new Map([[new SharedArrayBuffer(4), 'k']]),
365	    () => new Map([['k', { view: new DataView(new SharedArrayBuffer(4)) }]]),
366	    () => new Set([new SharedArrayBuffer(4)]),
367	    () => new Set([{ bytes: new Uint8Array(new SharedArrayBuffer(4)) }]),
368	    () => ({ table: new Map([[new Set([new SharedArrayBuffer(4)]), new DataView(new SharedArrayBuffer(4))]]) }),
369	    causeIsNonEnumerable,
370	    cyclic,
371	    aliased,
372	  ];
373	}
