490	test('shared bytes in clone-dropped properties (Date/RegExp auxiliaries, non-enumerable and symbol keys) leave the result legal', () => {
491	  const symbolKey = Symbol('hidden');
492	
493	  const date = new Date('2021-06-07T08:09:10.000Z');
494	  date.aux = new SharedArrayBuffer(8);
495	  class CustomDate extends Date {}
496	  const customDate = new CustomDate(0);
497	  customDate.aux = new SharedArrayBuffer(8);
498	
499	  const regexp = /pattern/gi;
500	  regexp.aux = new SharedArrayBuffer(8);
501	  class CustomRegExp extends RegExp {}
502	  const customRegexp = new CustomRegExp('pat');
503	  customRegexp.aux = new SharedArrayBuffer(8);
504	
505	  const plainBuffer = new ArrayBuffer(2);
506	  plainBuffer.dropped = new SharedArrayBuffer(2);
507	  const view = new Uint8Array([1, 2]);
508	  view.dropped = new SharedArrayBuffer(2);
509	
510	  const errorWithAux = new Error('boom');
511	  errorWithAux.details = new SharedArrayBuffer(4);
512	
513	  const nonEnumerable = {};
514	  Object.defineProperty(nonEnumerable, 'hidden', { value: new SharedArrayBuffer(4), enumerable: false });
515	
516	  const list = ['a', 'b'];
517	  Object.defineProperty(list, 'aux', { value: new SharedArrayBuffer(4), enumerable: false });
518	  // A non-enumerable index clones as a hole; the dropped bytes never count.
519	  const holey = [10, 20, 30];
520	  Object.defineProperty(holey, 1, { value: new SharedArrayBuffer(4), enumerable: false, configurable: true });
521	
522	  const symboled = {};
523	  symboled[symbolKey] = new SharedArrayBuffer(4);
524	
525	  const boxed = new Number(7);
526	  boxed.aux = new SharedArrayBuffer(4);
527	
528	  const result = {
529	    date, customDate, regexp, customRegexp, plainBuffer, view,
530	    errorWithAux, nonEnumerable, list, holey, symboled, boxed,
531	    keep: new Uint8Array([7, 8]),
532	  };
533	
534	  const workflow = linearEndWorkflow(result);
535	  assert.doesNotThrow(() => validateWorkflow(workflow));
536	
537	  const run = executeWorkflow(workflow, {});
538	  assert.equal(run.status, 'completed');
539	  const saved = run.result;
540	  assert.ok(saved.date instanceof Date);
541	  assert.ok(saved.customDate instanceof Date);
542	  assert.ok(saved.regexp instanceof RegExp);
543	  assert.ok(saved.customRegexp instanceof RegExp);
544	  assert.equal(saved.date.aux, undefined);
545	  assert.equal(saved.customDate.aux, undefined);
546	  assert.equal(saved.regexp.aux, undefined);
547	  assert.equal(saved.customRegexp.aux, undefined);
548	  assert.equal(saved.plainBuffer.dropped, undefined);
549	  assert.equal(saved.view.dropped, undefined);
550	  assert.equal(saved.errorWithAux.details, undefined);
551	  assert.equal(Object.hasOwn(saved.nonEnumerable, 'hidden'), false);
552	  assert.equal(Object.hasOwn(saved.list, 'aux'), false);
553	  assert.equal(Object.getOwnPropertySymbols(saved.symboled).length, 0);
554	  assert.equal(saved.boxed.aux, undefined);
