1386	// or null when execution should continue.
1387	function applyRegularNode(node, state) {
1388	  if (node.type === 'action') {
1389	    // Snapshot the legacy message at this action's own execution moment: the
1390	    // saved output is this run's independent deep copy, so editing nested
1391	    // fields, adding or deleting properties, or changing array members of the
1392	    // returned output never reaches the definition, another run, or an output
1393	    // this action recorded while another activated branch is still waiting.
1394	    // An unset, undefined or null message defaults to action:<node id>;
1395	    // "", 0 and false pass through untouched. Validation already guarantees
1396	    // that an explicit message is structured-cloneable, so this cannot throw
1397	    // mid-run.
1398	    const hasMessage = Object.hasOwn(node, 'message') && node.message !== undefined && node.message !== null;
1399	    const value = hasMessage ? structuredClone(node.message) : `action:${node.id}`;
1400	    setNodeOutput(state.context.output, node.id, value);
1401	  }
1402	  if (node.type === 'form') {
1403	    const compiled = formSchemas.get(node);
1404	    if (compiled) {
1405	      const formResult = processForm(node, state.context.input, compiled);
1406	      if (!formResult.ok) {
1407	        state.context.input = formResult.rollback;
1408	        return { status: 'invalid_input', context: state.context, trace: state.trace, errors: formResult.errors };
1409	      }
1410	    }
1411	  }
1412	  if (node.type === 'condition') {
1413	    const outcome = runCondition(compiledConditions.get(node), state.context.input, state.context.output, node.id);
1414	    if (!outcome.ok) {
1415	      return { status: 'invalid_condition', context: state.context, trace: state.trace, error: outcome.error };
1416	    }
1417	    state.activated.add(outcome.value ? node.then : node.else);
1418	  } else {
1419	    for (const target of successorTargets.get(node)) state.activated.add(target);
1420	  }
