1423	}
1424	
1425	// Verifies, before a single node can run, that every business operation and
1426	// every compensation operation in the definition has a function registered —
1427	// including actions on untaken branches and entry-unreachable nodes.
1428	function resolveImplementation(operations, name, nodeId, kind) {
1429	  if (!isUsableObject(operations)
1430	    || !Object.hasOwn(operations, name)
1431	    || typeof operations[name] !== 'function') {
1432	    throw new Error(`action node ${nodeId}: ${kind} operation "${name}" has no function implementation; pass it to executeWorkflowAsync`);
1433	  }
1434	  return operations[name];
1435	}
1436	
1437	function verifyOperations(nodes, operations) {
1438	  for (const node of nodes.values()) {
1439	    const binding = actionBindings.get(node);
1440	    if (binding && binding.name !== null) {
1441	      resolveImplementation(operations, binding.name, node.id, 'business');
1442	    }
1443	    if (binding && binding.compensation !== null) {
1444	      resolveImplementation(operations, binding.compensation.name, node.id, 'compensation');
1445	    }
1446	  }
1447	}
1448	
1449	// The optional fourth argument of executeWorkflowAsync carries an
1450	// AbortSignal as `{ signal }`. Omitting it — or passing undefined, or an
1451	// options object without a signal — keeps the previous behavior; anything
1452	// else is a caller error reported before a single node executes.
1453	function resolveRunSignal(options) {
1454	  if (options === undefined) return null;
1455	  if (!isUsableObject(options)) {
1456	    throw new TypeError('executeWorkflowAsync options must be an object with an optional "signal" AbortSignal');
1457	  }
1458	  if (!Object.hasOwn(options, 'signal') || options.signal === undefined) return null;
1459	  const { signal } = options;
1460	  if (signal instanceof AbortSignal) return signal;
1461	  throw new TypeError('executeWorkflowAsync options.signal must be an AbortSignal');
1462	}
1463	
1464	export function executeWorkflow(workflow, input = {}) {
1465	  const nodes = validateWorkflow(workflow);
1466	  // Business operations are asynchronous: the synchronous entry must refuse
1467	  // a workflow that names any before a single node executes.
1468	  for (const node of nodes.values()) {
1469	    const binding = actionBindings.get(node);
1470	    if (binding && binding.name !== null) {
1471	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
1472	    }
1473	  }
1474	
1475	  const state = createRunState(nodes, workflow, input);
1476	
1477	  for (;;) {
1478	    const step = advanceSchedule(state);
1479	
1480	    if (step.kind === 'blocked') {
1481	      return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes: step.waiting };
1482	    }
1483	    if (step.kind === 'completed') {
1484	      return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
1485	    }
1486	    if (step.kind === 'end') continue;
1487	
1488	    const early = applyRegularNode(step.node, state);
1489	    if (early) return early;
1490	  }
1491	}
1492	
1493	// Attaches compensation results to a failed run. Successful outputs and the
1494	// original terminal status stay untouched; compensation records live on
1495	// their own fields, never in the regular node trace.
1496	async function withCompensation(result, state, operations) {
1497	  const outcome = await compensateRun(state, operations);
1498	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1499	  result.compensationAttempts = outcome.attempts;
1500	  return result;
1501	}
1502	
1503	// The cancelled terminal shape: the run stops where it is, keeps the
1504	// context, trace and attempt records produced so far, and never carries a
1505	// success result. Compensation for already-succeeded actions is attached by
1506	// withCompensation under the usual rules.
1507	function cancelledResult(state) {
1508	  return {
1509	    status: 'cancelled',
1510	    context: state.context,
1511	    trace: state.trace,
1512	    actionAttempts: state.actionAttempts,
1513	  };
1514	}
1515	
1516	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1517	  const signal = resolveRunSignal(options);
1518	  const nodes = validateWorkflow(workflow);
1519	  verifyOperations(nodes, operations);
1520	
1521	  const state = createRunState(nodes, workflow, input);
1522	
1523	  // A signal that is already aborted stops the run before the first node —
1524	  // but only after the definition and the operation registrations above have
1525	  // been checked. Nothing executes and nothing is compensated.
1526	  if (signal && signal.aborted) {
1527	    return withCompensation(cancelledResult(state), state, operations);
1528	  }
1529	
1530	  for (;;) {
1531	    // Once the signal fires, no new regular node runs and no new business
1532	    // action attempt starts; the run ends cancelled with whatever state it
1533	    // reached, even if an end node was already visited on another branch.
1534	    if (signal && signal.aborted) {
1535	      return withCompensation(cancelledResult(state), state, operations);
1536	    }
1537	
1538	    const step = advanceSchedule(state);
1539	
1540	    if (step.kind === 'blocked') {
1541	      // Unmet dependencies end the run; successful compensable actions are
1542	      // rolled back even though an end node may already have been reached.
1543	      return withCompensation({
1544	        status: 'blocked', context: state.context, trace: state.trace,
1545	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1546	      }, state, operations);
1547	    }
1548	    if (step.kind === 'completed') {
1549	      // A completed run never invokes compensation.
1550	      return {
1551	        status: 'completed', result: state.endResult, context: state.context,
1552	        trace: state.trace, actionAttempts: state.actionAttempts,
1553	        compensationStatus: 'not_needed', compensationAttempts: [],
1554	      };
1555	    }
1556	    if (step.kind === 'end') continue;
1557	
1558	    const ready = step.node;
1559	    if (ready.type === 'action') {
1560	      const binding = actionBindings.get(ready);
1561	      if (binding.name !== null) {
1562	        // Nodes execute one at a time in declaration order; awaiting here
1563	        // never lets another node jump ahead.
1564	        const actionResult = await runBusinessAction(
1565	          ready, binding, operations[binding.name], state.context, state.actionAttempts, signal);
1566	        if (!actionResult.ok) {
1567	          if (actionResult.cancelled) {
1568	            // Cancelled while the action was in flight or waiting to retry:
1569	            // the attempt records produced so far stay as they are.
1570	            return withCompensation(cancelledResult(state), state, operations);
1571	          }
1572	          // Retries are exhausted: stop immediately with prior input/output
1573	          // preserved, no output for this node and no successors activated —
1574	          // even if an end node was already reached — then compensate every
1575	          // earlier successful action that asked for it.
1576	          return withCompensation({
1577	            status: 'action_failed', nodeId: ready.id, attempts: binding.retry.attempts,
1578	            error: actionResult.error, context: state.context, trace: state.trace,
1579	            actionAttempts: state.actionAttempts,
1580	          }, state, operations);
1581	        }
1582	        // Capture the compensation snapshots from the state before the new
1583	        // output key lands: the action's own return value is handed to the
1584	        // compensation separately as its third argument.
1585	        const compensationSnapshot = binding.compensation === null ? null : {
1586	          input: structuredClone(state.context.input),
1587	          output: structuredClone(state.context.output),
1588	          result: structuredClone(actionResult.value),
1589	        };
1590	        setNodeOutput(state.context.output, ready.id, actionResult.value);
1591	        if (compensationSnapshot) {
1592	          // Each node completes at most once, so retried-then-successful
1593	          // actions and shared join nodes are scheduled for compensation
1594	          // exactly once.
1595	          state.compensable.push({ nodeId: ready.id, binding, snapshot: compensationSnapshot });
1596	        }
1597	        for (const target of successorTargets.get(ready)) state.activated.add(target);
1598	        state.completed.add(ready.id);
1599	        continue;
1600	      }
1601	    }
1602	
1603	    const early = applyRegularNode(ready, state);
1604	    if (early) {
1605	      early.actionAttempts = state.actionAttempts;
1606	      // A failed form (invalid_input) or failed condition evaluation
1607	      // (invalid_condition) ends normal execution and triggers compensation
1608	      // of the successful business actions that ran earlier.
1609	      return withCompensation(early, state, operations);
1610	    }
1611	  }
1612	}
